report=dict(stage=201,same_boot200=True,kernel_build=183,uptime_seconds=float(Path('/proc/uptime').read_text().split()[0]),taint=0,fault_counts=counts,remoteprocs=rp,sensor_proxy=has,mm191_loaded_file_unchanged=True,mm_state=int(m['State']),mm_failed_reason=int(m['StateFailedReason']),mm_power_state=int(m['PowerState']),bearers=0,gps_enabled=0,gps_refresh_rate=30,signals_location=False,desktop_location_setting_restored_false=True,temporary_geoclue_test_policy_desktop_and_executable_removed=True,base_geoclue_configuration_exact=True,assist_source_sha256=hashlib.sha256(helper.read_bytes()).hexdigest(),assist_openrc_default_enabled=True,assist_idle=True,validated_auto_activation_worker_starts=1,validated_auto_activation_worker_completions=1,current_idle_service_after_restart_worker_starts=0,current_idle_service_after_restart_worker_completions=0,controlled_stale_injection_returned_aborted_and_kept_current_window=True,full_automatic_stale_refresh_native_path_not_yet_proven=True,normal_camss200_four_domains_unchanged=True,nv_sources_unchanged=True,reboot_or_flash_performed=False,real_gnss_fix_not_obtained=True)
(root/'k201-idle-normalization/correction.json').write_text(json.dumps(dict(stage=201,earlier_causal_label_not_proven=True,actual_observed_before=dict(Enabled=0,SignalsLocation=1,GpsRefreshRate=0),normalization_to=dict(Enabled=0,SignalsLocation=0,GpsRefreshRate=30),initial_stage_refresh_and_signal_fields_not_recorded=True),indent=2)+'\n')
